import {esc,empty} from './presentation.mjs';

export function recommendationsView(bundle,{feedback=true}={}) {
 if(!bundle)return '<section class="panel panel-pad section-gap"><h2>Suggested next steps</h2><p role="status">Learning suggestions are unavailable. Your lessons and bookings are still available.</p><button class="secondary" id="refresh">Retry suggestions</button></section>';
 const items=bundle.items||[];
 return `<section class="panel panel-pad section-gap" aria-labelledby="recommendations-title"><h2 id="recommendations-title">Suggested next steps</h2><p class="sub">Based on your saved progress and recent instructor scores. Your instructor guides practical training.</p>${items.map(item=>`<article class="recommendation-item"><h3>${esc(item.title)}</h3><p>${esc(item.reason)}</p>${!item.resource_available?'<p class="hint">The school has not added a video for this topic yet.</p>':''}<div class="recommendation-actions"><button class="secondary" data-nav="syllabus">View learning plan</button>${feedback?`${item.feedback==='helpful'?'<span role="status">Marked helpful</span>':`<button class="link" data-recommendation-feedback="${esc(item.recommendation_id)}" data-feedback="helpful">Helpful</button>`}<button class="link" data-recommendation-feedback="${esc(item.recommendation_id)}" data-feedback="dismissed">Hide until progress changes</button>`:''}</div></article>`).join('')||empty(bundle.completed?'All curriculum milestones completed':'No suggestions to show',bundle.completed?'Review your progress with your instructor.':'Hidden suggestions return when progress, resources or recent assessment scores change.')}</section>`;
}
